import assert from 'node:assert/strict';
import { listTools, callTool } from './server.mjs';

test('lists the users_get_many tool with a strict schema', async () => {
  const tools = await listTools();
  assert.equal(tools.length, 1);
  const t = tools[0];
  assert.equal(t.name, 'users_get_many');
  const s = t.inputSchema;
  assert.equal(s.type, 'object');
  assert.equal(s.required[0], 'user_ids');
  assert.equal(s.additionalProperties, false);
  assert.equal(s.properties.user_ids.minItems, 1);
  assert.equal(s.properties.user_ids.maxItems, 5);
  assert.equal(s.properties.user_ids.uniqueItems, true);
});

test('batch lookup returns one line per requested id in request order', async () => {
  const r = await callTool('users_get_many', { user_ids: ['u3', 'u1'] });
  const text = r.content[0].text;
  const lines = text.split('\n');
  assert.equal(lines.length, 2);
  assert.match(lines[0], /^u3: Edsger$/);
  assert.match(lines[1], /^u1: Ada$/);
});

test('batch lookup marks missing users without failing the batch', async () => {
  const r = await callTool('users_get_many', { user_ids: ['u2', 'missing'] });
  const text = r.content[0].text;
  assert.match(text, /Grace/);
  assert.match(text, /missing: not found/);
  const lines = text.split('\n');
  assert.equal(lines.length, 2);
  assert.match(lines[0], /^u2: Grace$/);
  assert.match(lines[1], /^missing: not found$/);
});

